package com.vibeguard.samples.emailchange; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Validates one-time verification codes before confirming an email change. */ @RestController @RequestMapping("/api/email-changes") public class EmailChangeController { private final Map<String,Change> changes=new ConcurrentHashMap<>(); private final SecureRandom random=new SecureRandom(); @PostMapping public ResponseEntity<Void> request(@Valid @RequestBody Request request)throws Exception{String code=String.valueOf(random.nextInt(900000)+100000);changes.put(hash(code),new Change(request.userId(),request.newEmail(),Instant.now().plusSeconds(900)));return ResponseEntity.accepted().build();}@PostMapping("/confirm") public ResponseEntity<Void> confirm(@Valid @RequestBody Confirm input)throws Exception{Change change=changes.remove(hash(input.code()));return change==null||Instant.now().isAfter(change.expiresAt())?ResponseEntity.badRequest().build():ResponseEntity.noContent().build();}private String hash(String code)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(code.getBytes(StandardCharsets.UTF_8)));}record Request(@NotBlank String userId,@Email String newEmail){}record Confirm(@NotBlank String code){}record Change(String userId,String email,Instant expiresAt){} }
